[tikz]\begin{tikzpicture}[every node/.style={font=\large}, x=1.1cm, y=1.1cm]
\fill[gray!35] (1,0.65) -- plot[domain=1:4, samples=60, variable=\x] ({\x},{2.6-0.12*(\x-2.5)*(\x-2.5)}) -- plot[domain=4:1, samples=2, variable=\x] ({\x},{0.5+0.15*\x}) -- cycle;
\draw[->] (-0.6,0) -- (5.4,0) node[right] {$x$};
\draw[->] (0,-1.6) -- (0,3.4) node[above] {$y$};
\draw[thick, <->, domain=0.2:5, samples=60, variable=\x] plot ({\x},{2.6-0.12*(\x-2.5)*(\x-2.5)});
